});

test('world uninstall runs cleanup and removes listener extension', () => {
  const world = new World();
  let handled = 0;
  let cleaned = 0;

  const extension = defineExtension('listenerExtension', (w) => {
    const off = w.on('x', () => {
      handled++;
    });
    return () => {
      cleaned++;
      off();
    };
